sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        if (method !== 'GET') {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        var storeId = request.pathParams.store_id;
        if (!storeId) {
            response.setStatus(400);
            return { success: false, error: 'store_id is required' };
        }
        var isHistory = request.pathParams.sub === 'history';
        var body = isHistory ? getHistory(storeId, request.queryParams) : getLatest(storeId);
        response.setStatus(body.success ? 200 : 400);
        return body;
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function getLatest(storeId) {
        var gr = new GlideRecord('x_2145749_qc_pulse_score');
        gr.addQuery('dark_store', storeId);
        gr.orderByDesc('snapshot_time');
        gr.setLimit(1);
        gr.query();
        if (!gr.next()) {
            return { success: false, error: 'No PulseScore snapshot for this store yet' };
        }
        return { success: true, result: toObj(gr) };
    }

    function getHistory(storeId, qp) {
        var gr = new GlideRecord('x_2145749_qc_pulse_score');
        gr.addQuery('dark_store', storeId);
        gr.orderByDesc('snapshot_time');
        var limit = parseInt(qp.limit, 10) || 30;
        gr.setLimit(limit);
        gr.query();
        var results = [];
        while (gr.next()) {
            results.push(toObj(gr));
        }
        return { success: true, result: results };
    }

    function toObj(gr) {
        var breakdown = null;
        try {
            breakdown = JSON.parse(gr.breakdown.toString());
        } catch (e) {
            breakdown = gr.breakdown.toString();
        }
        return {
            sys_id: gr.getUniqueValue(),
            store: gr.dark_store.getDisplayValue(),
            score: gr.score.toString(),
            band: gr.band.toString(),
            breakdown: breakdown,
            open_complaint_count: gr.open_complaint_count.toString(),
            open_store_issue_count: gr.open_store_issue_count.toString(),
            as_of: gr.snapshot_time.toString()
        };
    }
})(request, response);
